import { test, expect } from '@playwright/test';

test.describe('Sidebar Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-website-url.com');
  });

  test('should expand the sidebar on click', async ({ page }) => {
    const sidebarToggle = page.getByRole('button', { name: /toggle sidebar/i });
    await sidebarToggle.click();

    const sidebar = page.getByRole('navigation');
    await expect(sidebar).toBeVisible();
  });

  test('should collapse the sidebar on click', async ({ page }) => {
    const sidebarToggle = page.getByRole('button', { name: /toggle sidebar/i });
    await sidebarToggle.click(); // Expand first
    await sidebarToggle.click(); // Collapse

    const sidebar = page.getByRole('navigation');
    await expect(sidebar).toBeHidden();
  });
});
